import { topUpPrices, type Resolution } from "./prices";
import { countMissingPrices, tickersMissingPrices } from "./universe";

/**
 * Background price top-up.
 *
 * Downloading a batch of companies gets the SEC half done in minutes; the
 * price half depends on providers whose free tiers allow a few dozen symbols
 * an hour. Rather than leaving the user to press "Doplnit chybějící ceny"
 * every twenty minutes — or run a cron job, which a Windows install cannot —
 * the app keeps coming back on its own until every stored company has prices.
 *
 * State lives on `globalThis` so a dev-server module reload does not lose a
 * timer that is already ticking.
 */

export type TopUpStatus = {
  /** A run is in progress or the next one is scheduled. */
  active: boolean;
  /** Currently talking to a provider (as opposed to waiting for a quota). */
  running: boolean;
  /** When the next attempt is due, if waiting. */
  nextAt: string | null;
  startedAt: string | null;
  rounds: number;
  /** Companies still without prices. */
  missing: number;
  /** Outcome of the latest round, for the panel. */
  last: string | null;
};

type State = {
  timer: NodeJS.Timeout | null;
  running: boolean;
  nextAt: number | null;
  startedAt: number | null;
  rounds: number;
  last: string | null;
  resolution: Resolution | undefined;
  /** Set by stop() while a round is in flight; honoured once it returns. */
  stopRequested: boolean;
  /** Non-quota failures per ticker; a symbol no provider knows is dropped. */
  failures: Map<string, number>;
};

const RETRY_MS = 20 * 60 * 1000;
/** Give up after this long so a hopeless queue cannot poll forever. */
const MAX_LIFETIME_MS = 48 * 60 * 60 * 1000;
const BATCH = 45;
const MAX_FAILURES = 3;

const g = globalThis as typeof globalThis & { __stocksTopUp?: State };

function state(): State {
  if (!g.__stocksTopUp) {
    g.__stocksTopUp = {
      timer: null,
      running: false,
      nextAt: null,
      startedAt: null,
      rounds: 0,
      last: null,
      resolution: undefined,
      stopRequested: false,
      failures: new Map(),
    };
  }
  return g.__stocksTopUp;
}

export function topUpStatus(): TopUpStatus {
  const s = state();
  return {
    active: s.running || s.timer !== null,
    running: s.running,
    nextAt: s.nextAt ? new Date(s.nextAt).toISOString() : null,
    startedAt: s.startedAt ? new Date(s.startedAt).toISOString() : null,
    rounds: s.rounds,
    missing: countMissingPrices(),
    last: s.last,
  };
}

function finish(s: State, message: string): void {
  s.last = message;
  s.timer = null;
  s.nextAt = null;
  s.startedAt = null;
  s.failures.clear();
}

function schedule(s: State, delayMs: number): void {
  s.nextAt = Date.now() + delayMs;
  s.timer = setTimeout(() => {
    s.timer = null;
    s.nextAt = null;
    void round(s);
  }, delayMs);
  // Never keep the process alive just for this.
  s.timer.unref?.();
}

async function round(s: State): Promise<void> {
  if (s.running) return;
  s.running = true;
  s.rounds++;

  try {
    const queue = tickersMissingPrices(500).filter(
      (t) => (s.failures.get(t.ticker) ?? 0) < MAX_FAILURES,
    );

    if (queue.length === 0) {
      const left = countMissingPrices();
      finish(
        s,
        left === 0
          ? "Všechny stažené firmy mají ceny."
          : `Zbývá ${left} firem, které žádný poskytovatel nezná — ty už nezkouším.`,
      );
      return;
    }

    let ok = 0;
    let quota: string | null = null;

    for (const item of queue.slice(0, BATCH)) {
      if (s.stopRequested) break;
      try {
        await topUpPrices(item.ticker, undefined, s.resolution);
        ok++;
      } catch (e) {
        const msg = (e as Error).message;
        // Same rule as the manual batch: a symbol that 404s is not a quota.
        const unknownSymbol = /HTTP 404|nezná symbol/i.test(msg);
        if (/limit vyčerpán|kvóta/i.test(msg) && !unknownSymbol) {
          quota = msg;
          break;
        }
        s.failures.set(item.ticker, (s.failures.get(item.ticker) ?? 0) + 1);
      }
    }

    const left = countMissingPrices();
    const stamp = new Date().toLocaleTimeString("cs-CZ", { hour: "2-digit", minute: "2-digit" });

    if (s.stopRequested) {
      finish(s, `${stamp}: doplňování zastaveno, bez cen zbývá ${left}.`);
      return;
    }
    if (left === 0) {
      finish(s, `${stamp}: doplněno ${ok}, všechny firmy mají ceny.`);
      return;
    }
    if (s.startedAt && Date.now() - s.startedAt > MAX_LIFETIME_MS) {
      finish(s, `${stamp}: po dvou dnech končím, bez cen zůstává ${left} firem.`);
      return;
    }

    s.last =
      `${stamp}: doplněno ${ok}, bez cen zbývá ${left}.` +
      (quota ? ` Kvóta vyčerpaná (${quota.slice(0, 80)}), zkusím to znovu za 20 min.` : "");
    schedule(s, RETRY_MS);
  } finally {
    s.running = false;
    s.stopRequested = false;
  }
}

/**
 * Start the loop, or leave a running one alone. Returns immediately; the first
 * round begins on the next tick so the caller's response is not held up.
 */
export function startPriceTopUp(resolution?: Resolution): TopUpStatus {
  const s = state();
  if (!s.running && s.timer === null) {
    s.startedAt = Date.now();
    s.rounds = 0;
    s.last = null;
    s.resolution = resolution;
    s.stopRequested = false;
    s.failures.clear();
    schedule(s, 0);
  }
  return topUpStatus();
}

/** Cancel the pending attempt. A round already talking to a provider finishes. */
export function stopPriceTopUp(): TopUpStatus {
  const s = state();
  if (s.timer) clearTimeout(s.timer);
  if (s.running) {
    s.stopRequested = true;
    s.timer = null;
    s.nextAt = null;
  } else {
    finish(s, "Doplňování zastaveno.");
  }
  return topUpStatus();
}
